  /* ---- Chuỗi cốt truyện tân thủ (story.js) — "Đêm Máu Làng Phong Diệp" ---- */
  story_title: "Đêm Máu Làng Phong Diệp",
  story_narrator: "Người kể chuyện",
  story_skip: "Bỏ qua",
  story_next: "Tiếp tục",
  story_begin: "Bắt đầu hành trình",
