  story_you: "Ngươi",
  story_dan_lang: "Dân làng",
  story_trai_chu: "Trại chủ Hắc Phong",
  story_cha_nuoi: "Lâm Đại Sơn",
  story_giong_co: "Giọng cổ xưa",
  /* Ô 1 — Lễ hội */
  intro_p1_l1: "Đêm rằm tháng bảy, làng Phong Diệp mở lễ Trắc Linh Căn mười năm một lần. Thiếu niên bước lên đài đá, tim đập thình thịch.",
  intro_p1_l2: "Đặt tay lên Trắc Linh Thạch, tâm tĩnh như nước!",
  intro_p1_l3: "Cha, mẹ... con nhất định không để hai người thất vọng.",
  /* Ô 2 — Dị tượng chín màu */
  intro_p2_l1: "Ầm! Cột linh quang chín màu xuyên thủng tầng mây! Ngàn năm tu tiên giới chưa từng có dị tượng này.",
  intro_p2_l2: "Trời ơi... Cửu Sắc Linh Căn! Yêu nghiệt xuất thế!",
  intro_p2_l3: "Cuối cùng... cũng đợi được ngươi. Mảnh thứ tám.",
  /* Ô 3 — Đêm máu */
  intro_p3_l1: "Nửa đêm, tiếng vó ngựa xé toang giấc mộng. Hắc Phong Trại tràn vào làng như thác lũ.",
  intro_p3_l2: "Giao ra thằng nhãi có Cửu Sắc Linh Căn và miếng ngọc bội! Gà chó không tha!",
  intro_p3_l3: "Con chạy đi! Chạy vào rừng! Đừng quay đầu lại!",
  intro_p3_l4: "CHA! MẸ!",
  /* Ô 4 — Ngọc bội phát sáng */
  intro_p4_l1: "Trong biển lửa, miếng ngọc bội bỗng nóng rực. Một giọng nói cổ xưa vang lên trong đầu.",
  intro_p4_l2: "Mảnh thứ tám... Luân hồi ngàn năm... Cuối cùng ngươi cũng tỉnh.",
  intro_p4_l3: "Tiểu tử, muốn báo thù thì đứng dậy đi theo lão phu. Con đường phía trước — là tiên lộ vạn dặm đầy máu.",
  story_next_quest: "Đã nhận nhiệm vụ mới: {n}",
  taycot_drink: "Tẩy cốt phạt tủy thành công! Căn Cốt tăng lên cấp {n}.",
  it_pill_taycotdan: "Tẩy Cốt Đan",
  it_pill_taycotdan_desc: "Đan dược do Đại Phu luyện chế từ Tẩy Cốt Thảo. Uống vào tẩy cốt phạt tủy, tăng 1 cấp Căn Cốt vĩnh viễn. Lần đầu uống sẽ ĐỊNH PHẨM CHẤT căn cốt.",
  it_pill_taycotdan_trung: "Tẩy Cốt Đan Trung Phẩm",
  it_pill_taycotdan_trung_desc: "Tẩy Cốt Đan phẩm trung. Uống: +2 cấp Căn Cốt, tỉ lệ roll phẩm chất cao tăng.",
  it_pill_taycotdan_thuong: "Tẩy Cốt Đan Thượng Phẩm",
  it_pill_taycotdan_thuong_desc: "Tẩy Cốt Đan phẩm thượng. Uống: +3 cấp Căn Cốt, tỉ lệ roll phẩm chất cao tăng mạnh.",
  it_pill_taycotdan_thien: "Tẩy Cốt Đan Thiên Phẩm",
  it_pill_taycotdan_thien_desc: "Tẩy Cốt Đan phẩm thiên. Uống: +5 cấp Căn Cốt, tỉ lệ roll phẩm chất cao cao nhất.",
  it_pill_khaimachdan: "Khai Mạch Đan",
  it_pill_khaimachdan_desc: "Đan dược khai mở kinh mạch. Uống: mở thêm 1 linh căn ngũ hành ngẫu nhiên chưa khai mở (tối đa 5).",
  it_pill_khaimachdan_trung: "Khai Mạch Đan Trung Phẩm",
