  q_pet_intro_desc: "Gặp Tuần Thú Sư để nhận trứng linh thú đầu tiên của ngươi.",
  q_story_01: "Sơ Nhập Tiên Đồ",
  q_story_01_desc: "Theo lời Lão Dẫn Đường, đến gặp Đại Phu ở Thanh Vân Trấn.",
  q_story_02: "Thu Thập Tẩy Cốt Thảo",
  q_story_02_desc: "Ngươi đã lập công trừ hại bốn phương. Đại Phu quyết định luyện Tẩy Cốt Đan cho ngươi — thu thập 3 Tẩy Cốt Thảo (rớt từ quái) mang về.",
  q_story_03: "Tẩy Cốt Phạt Tủy",
  q_story_03_desc: "Nhận Tẩy Cốt Đan từ Đại Phu. Mở Hành Trang, uống đan để tăng 1 cấp Căn Cốt — và ĐỊNH PHẨM CHẤT căn cốt (Phàm/Huyền/Địa/Thiên/Tiên).",
  q_story_04: "Trừ Hại Dã Trư",
