  npc_truong_lang_meet1: "Tiểu tử, đêm nay là lễ Trắc Linh Căn mười năm một lần của làng. Lên đài đá, đặt tay lên Trắc Linh Thạch đi!",
  npc_truong_lang_meet2: "Trời ơi... Cửu Sắc Linh Căn! Ngàn năm tu tiên giới chưa từng có! Mau... mau đi tìm chỗ trốn, tin này mà lọt ra ngoài...",
  npc_co_tran_tu_meet1: "Tiểu tử, muốn báo thù thì đứng dậy đi theo lão phu. Con đường phía trước — là tiên lộ vạn dặm đầy máu.",
  npc_co_tran_tu_meet2: "Muốn báo thù, trước tiên phải Tẩy Cốt Phạt Tủy, bước vào Luyện Khí. Cầm lấy thanh kiếm gỗ này mà phòng thân.",
  npc_to_uyen_nhi_meet1: "Ca ca, muội cũng có Băng linh căn! Sau này muội sẽ bảo vệ huynh!",
  npc_to_uyen_nhi_meet2: "Diệp Vân ca ca lúc nào cũng bộc trực như vậy. Ba chúng ta cùng bái nhập tông môn nhé!",
  npc_diep_van_meet1: "Huynh đệ! Ta có Kim linh căn, kiếm tu là hợp nhất! Sau này vào sinh ra tử cùng nhau!",
  npc_diep_van_meet2: "Hắc Phong Trại nợ máu phải trả bằng máu. Đi, theo Cổ tiền bối tu tiên báo thù!",
