  sk_hoa_vu_luu_tinh: "Hỏa Vũ Lưu Tinh",
  sk_hoa_vu_luu_tinh_desc: "Mưa lửa diện rộng 180% công.",
  sk_linh_thuan: "Linh Thuẫn",
  sk_linh_thuan_desc: "Thuẫn linh lực, +40% phòng thủ trong 15 giây.",
  sk_ba_vuong_quyen: "Bá Vương Quyền",
  sk_ba_vuong_quyen_desc: "Quyền kình bá đạo, sát thương đơn 220% công.",
  sk_chan_dia_chuong: "Chấn Địa Chưởng",
  sk_chan_dia_chuong_desc: "Chưởng chấn mặt đất, sát thương diện rộng 160% công.",
  sk_kim_cuong_bat_hoai: "Kim Cang Bất Hoại",
  sk_kim_cuong_bat_hoai_desc: "Thân thể kim cang, +80% phòng thủ và khiên 30% HP trong 15 giây.",
  sk_kimdan_kiem_y: "Kim Đan Kiếm Ý",
  sk_kimdan_kiem_y_desc: "Kiếm ý Kim Đan, sát thương đơn 400% công, xuyên giáp 20%.",
  sk_kimdan_loi_phap: "Kim Đan Lôi Pháp",
  sk_kimdan_loi_phap_desc: "Lôi pháp Kim Đan, sát thương diện rộng 320% công.",
  sk_kimdan_the_quyen: "Kim Đan Thể Quyền",
  sk_kimdan_the_quyen_desc: "Quyền ý Kim Đan, sát thương đơn 360% công, khiên 20% HP.",
