  it_manual_boss_datru_desc: "Bí tịch boss Đá Trụ Vương (Địa phẩm). Học để mở Man Hoang Chấn Địa.",
  it_manual_boss_langvuong: "Bí Tịch Lang Vương Khiếu Nguyệt",
