  it_manual_boss_huyetma: "Bí Tịch Huyết Ma Trảm",
  it_manual_boss_huyetma_desc: "Bí tịch boss Huyết Ma Vương (Địa phẩm, Ma Đạo). Học để mở Huyết Ma Trảm.",
  it_manual_boss_thientuong: "Bí Tịch Thiên Lôi Phá",
  it_manual_boss_thientuong_desc: "Bí tịch boss Thiên Tướng (Thiên phẩm). Học để mở Thiên Lôi Phá.",
  sk_man_hoang_chan_dia: "Man Hoang Chấn Địa",
  sk_man_hoang_chan_dia_desc: "Chấn động mặt đất, sát thương diện rộng 300% công.",
  sk_lang_vuong_khieu_nguyet: "Lang Vương Khiếu Nguyệt",
  sk_lang_vuong_khieu_nguyet_desc: "Tiếng hú uy hiếp, sát thương đơn 340% công, gây Hoảng Sợ 2s.",
  sk_bach_cot_ma_trao: "Bạch Cốt Ma Trảo",
  sk_bach_cot_ma_trao_desc: "Trảo xương trắng, sát thương đơn 400% công, gây Xuất Huyết 4s.",
  sk_doc_vu_cuong_trieu: "Độc Vụ Cuồng Triều",
  sk_doc_vu_cuong_trieu_desc: "Sóng độc cuồng nộ, sát thương diện rộng 420% công, gây Trúng Độc 5s.",
  sk_ma_long_phe_hon: "Ma Long Phệ Hồn",
  sk_ma_long_phe_hon_desc: "Ma long nuốt hồn, sát thương đơn 500% công, gây Hoảng Sợ 3s.",
  sk_thien_loi_pha: "Thiên Lôi Phá",
  sk_thien_loi_pha_desc: "Thiên lôi giáng xuống, sát thương diện rộng 450% công, gây Choáng 2s.",
  boss_manual_drop: "⚜️ BÍ TỊCH BOSS: {name}!",
  it_manual_the_1: "Bí Tịch Bá Vương Quyền",
  it_manual_the_1_desc: "Học để mở Bá Vương Quyền (chủ động · Phàm phẩm).",
