  it_manual_the_2_desc: "Học để mở Chấn Địa Chưởng (chủ động · Địa phẩm).",
  it_manual_the_3: "Bí Tịch Kim Cang",
  it_manual_the_3_desc: "Học để mở Kim Cang Bất Hoại (chủ động · Thiên phẩm).",
  it_manual_ps_kiem_tam: "Bí Tịch Kiếm Tâm",
  it_manual_ps_kiem_tam_desc: "Học để mở bị động Kiếm Tâm (+10% công mỗi cấp).",
  it_manual_ps_linh_mach: "Bí Tịch Linh Mạch",
  it_manual_ps_linh_mach_desc: "Học để mở bị động Linh Mạch (hồi 2% linh lực/5s mỗi cấp).",
  it_manual_ps_the_phach: "Bí Tịch Thể Phách",
  it_manual_ps_the_phach_desc: "Học để mở bị động Thể Phách (+8% HP tối đa mỗi cấp).",
  it_manual_ps_than_phap: "Bí Tịch Thân Pháp",
