  it_dan_ngung_dan_desc: "Golden Core pill. +15% breakthrough rate. Recipe: 5 Earth Spirit Fruit + 1 Tier-2 Beast Core.",
  it_dan_cuu_chuyen: "Nine-Revolution Pill",
  it_dan_cuu_chuyen_desc: "Golden Core pill. +8000 cultivation. Recipe: 3 Seven-Leaf Mushroom + 2 Earth Spirit Fruit.",
  it_dan_duong_anh: "Nascent Nurture Pill",
  it_dan_duong_anh_desc: "Nascent Soul pill. +20000 cultivation. Recipe: 5 Seven-Leaf Mushroom + 1 Tier-3 Beast Core.",
  it_dan_ho_mach: "Meridian Guard Pill",
  it_dan_ho_mach_desc: "Nascent Soul pill. +20% breakthrough rate. Recipe: 3 Seven-Leaf Mushroom + 2 Immortal Herb.",
  it_dan_than_du: "Spirit Wander Pill",
  it_dan_than_du_desc: "Deity Transformation pill. +50000 cultivation. Recipe: 5 Immortal Herb + 1 Tier-4 Beast Core.",
  it_dan_tu_than: "Spirit Focus Pill",
  it_dan_tu_than_desc: "Deity Transformation pill. Fully restores divine sense. Recipe: 3 Immortal Herb + 3 Seven-Leaf Mushroom.",
  it_dan_hu_linh: "Void Spirit Pill",
  it_dan_hu_linh_desc: "Void Refinement pill. +120000 cultivation. Recipe: 5 Immortal Herb + 2 Blood Essence + 1 Tier-4 Beast Core.",
  it_dan_co_ban: "Foundation Solid Pill",
  it_dan_co_ban_desc: "Void Refinement pill. No cultivation loss on defeat for 24h. Recipe: 3 Blood Essence + 5 Seven-Leaf Mushroom.",
  it_dan_hop_the: "Unity Pill",
  it_dan_hop_the_desc: "Body Integration pill. +20% breakthrough rate. Recipe: 1 Nine-Leaf Mushroom + 3 Blood Essence + 1 Tier-5 Beast Core.",
  it_dan_quy_nhat: "Oneness Pill",
  it_dan_quy_nhat_desc: "Body Integration pill. +300000 cultivation. Recipe: 1 Nine-Leaf Mushroom + 5 Immortal Herb.",
  it_dan_dai_thua: "Great Ascension Pill",
  it_dan_dai_thua_desc: "Mahayana pill. +25% breakthrough rate. Recipe: 2 Nine-Leaf Mushroom + 1 Tier-5 Beast Core.",
  it_dan_tien_linh: "Immortal Spirit Pill",
  it_dan_tien_linh_desc: "Mahayana pill. +800000 cultivation. Recipe: 2 Nine-Leaf Mushroom + 3 Blood Essence.",
  it_dan_do_kiep: "Tribulation Pill",
  it_dan_do_kiep_desc: "Tribulation pill. -30% lightning tribulation damage. Recipe: 3 Nine-Leaf Mushroom + 2 Tier-5 Beast Core.",
  it_dan_cuu_kiep: "Nine Tribulation Pill",
  it_dan_cuu_kiep_desc: "Tribulation pill. +2000000 cultivation. Recipe: 5 Nine-Leaf Mushroom.",
  rar_0: "Common", rar_1: "Fine", rar_2: "Superior", rar_3: "Rare", rar_4: "Epic", rar_5: "Legendary", rar_6: "Immortal",
  dokho_0: "Easy", dokho_1: "Medium", dokho_2: "Hard", dokho_3: "Extreme", dokho_4: "Unobtainable",
