  npc_u_minh_ton_gia: "Nether Venerable",
  npc_u_minh_ton_gia_greet: "The Nether is deep. What brings you here?",
  npc_u_minh_ton_gia_has_quest: "The nether is deep; fortune awaits the destined.",
  npc_u_minh_ton_gia_turnin: "Good. The Nether acknowledges your merit.",
