  npc_truong_lang: "Village Chief",
  npc_truong_lang_greet: "Hello, young one! Our village holds the spirit root ceremony tonight. You've come at the right time!",
  npc_truong_lang_has_quest: "The village needs help. Will you accept?",
  npc_truong_lang_turnin: "Excellent! The whole village thanks you.",
  npc_truong_lang_progress: "The work is unfinished; keep it up!",
  npc_truong_lang_alldone: "The village is peaceful now.",
  npc_co_tran_tu: "Co Tran Tu",
  npc_co_tran_tu_greet: "Hehe! Young one, I am Co Tran Tu, just passing by.",
  npc_co_tran_tu_has_quest: "Hehe, young one, I have an interesting task for you!",
  npc_co_tran_tu_turnin: "Not bad! You are indeed my chosen disciple.",
