  npc_truong_lang_meet1: "Young one, tonight is the village's once-in-a-decade Spirit Root Ceremony. Step onto the stone platform and place your hand on the Testing Stone!",
  npc_truong_lang_meet2: "Heavens... the Nine-Color Spirit Root! Unseen in a thousand years! Quick... hide, if word gets out...",
  npc_co_tran_tu_meet1: "Young one, if you want revenge, stand up and follow this old man. The road ahead is a thousand miles of blood on the immortal path.",
  npc_co_tran_tu_meet2: "For revenge, first cleanse bone and marrow, then step into Qi Refining. Take this wooden sword to defend yourself.",
  npc_to_uyen_nhi_meet1: "Brother, I have an Ice spirit root too! From now on I'll protect you!",
  npc_to_uyen_nhi_meet2: "Brother Diep Van is always so blunt. The three of us will join a sect together!",
  npc_diep_van_meet1: "Brother! I have a Metal spirit root — born for the sword! From now on we live and die together!",
  npc_diep_van_meet2: "Black Wind Bandits owe a blood debt. Come, follow Senior Co to cultivate and take revenge!",
  qg_cultivate_t: "Cultivate",
