  sk_kimdan_the_quyen_desc: "Golden Core fist intent, 360% ATK single-target, 20% HP shield.",
  it_manual_kiem_1: "Manual: Cloud Sword",
  it_manual_kiem_1_desc: "Learn to unlock Cloud-Piercing Sword (active \u00b7 Mortal tier).",
  it_manual_kiem_2: "Manual: Myriad Swords",
